-- Synthetic Machine Safety Analysis seed data; generated deterministically.
BEGIN TRANSACTION;
CREATE TABLE acknowledgement (acknowledgement_id TEXT PRIMARY KEY, alarm_event_id TEXT NOT NULL REFERENCES alarm_event(alarm_event_id), operator_id TEXT NOT NULL, ack_ts TEXT NOT NULL, ack_status TEXT NOT NULL, response_minutes INTEGER NOT NULL, issue_type TEXT);
CREATE TABLE alarm_definition (alarm_definition_id TEXT PRIMARY KEY, machine_id TEXT NOT NULL REFERENCES machine(machine_id), alarm_code TEXT NOT NULL, alarm_name TEXT NOT NULL, severity TEXT NOT NULL, ack_required TEXT NOT NULL, ack_sla_minutes INTEGER NOT NULL, nuisance_candidate TEXT NOT NULL, active_from TEXT NOT NULL, active_to TEXT);
CREATE TABLE alarm_event (alarm_event_id TEXT PRIMARY KEY, machine_id TEXT NOT NULL REFERENCES machine(machine_id), alarm_definition_id TEXT NOT NULL REFERENCES alarm_definition(alarm_definition_id), event_ts TEXT NOT NULL, severity TEXT NOT NULL, event_type TEXT NOT NULL, machine_state TEXT NOT NULL, interlock_state TEXT NOT NULL, operator_shift_id TEXT REFERENCES operator_shift(shift_id), source_event_id TEXT, replay_flag TEXT NOT NULL, nuisance_flag TEXT NOT NULL, issue_type TEXT);
CREATE TABLE corrective_action (corrective_action_id TEXT PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES incident(incident_id), action_description TEXT NOT NULL, owner_role TEXT NOT NULL, created_ts TEXT NOT NULL, completed_ts TEXT, action_status TEXT NOT NULL, verification_status TEXT NOT NULL, verified_ts TEXT, issue_type TEXT);
CREATE TABLE incident (incident_id TEXT PRIMARY KEY, machine_id TEXT NOT NULL REFERENCES machine(machine_id), alarm_event_id TEXT REFERENCES alarm_event(alarm_event_id), opened_ts TEXT NOT NULL, incident_type TEXT NOT NULL, severity TEXT NOT NULL, incident_status TEXT NOT NULL, trigger_context TEXT, resolved_ts TEXT, issue_type TEXT);
CREATE TABLE interlock (interlock_id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plant(plant_id), interlock_name TEXT NOT NULL, required_state TEXT NOT NULL, permitted_machine_states TEXT NOT NULL, lifecycle_state TEXT NOT NULL);
CREATE TABLE machine (machine_id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plant(plant_id), machine_name TEXT NOT NULL, machine_type TEXT NOT NULL, criticality TEXT NOT NULL, lifecycle_state TEXT NOT NULL, commissioned_on TEXT NOT NULL, retired_on TEXT);
CREATE TABLE machine_interlock (machine_id TEXT NOT NULL REFERENCES machine(machine_id), interlock_id TEXT NOT NULL REFERENCES interlock(interlock_id), valid_from TEXT NOT NULL, valid_to TEXT, PRIMARY KEY(machine_id,interlock_id,valid_from));
CREATE TABLE machine_state_event (state_event_id TEXT PRIMARY KEY, machine_id TEXT NOT NULL REFERENCES machine(machine_id), event_ts TEXT NOT NULL, from_state TEXT NOT NULL, to_state TEXT NOT NULL, interlock_id TEXT NOT NULL REFERENCES interlock(interlock_id), interlock_state TEXT NOT NULL, source_alarm_event_id TEXT REFERENCES alarm_event(alarm_event_id), issue_type TEXT);
CREATE TABLE machine_zone (machine_id TEXT NOT NULL REFERENCES machine(machine_id), safety_zone_id TEXT NOT NULL REFERENCES safety_zone(safety_zone_id), PRIMARY KEY(machine_id,safety_zone_id));
CREATE TABLE operator_shift (shift_id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plant(plant_id), machine_id TEXT NOT NULL REFERENCES machine(machine_id), operator_id TEXT NOT NULL, shift_name TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, effective_from TEXT NOT NULL, effective_to TEXT NOT NULL);
CREATE TABLE plant (plant_id TEXT PRIMARY KEY, plant_name TEXT NOT NULL, site_code TEXT UNIQUE NOT NULL, country TEXT NOT NULL, timezone TEXT NOT NULL, lifecycle_state TEXT NOT NULL, effective_from TEXT NOT NULL, effective_to TEXT);
CREATE TABLE safety_zone (safety_zone_id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plant(plant_id), zone_name TEXT NOT NULL, risk_level TEXT NOT NULL, effective_from TEXT NOT NULL, effective_to TEXT);
CREATE INDEX idx_alarm_machine_ts ON alarm_event(machine_id,event_ts);
CREATE INDEX idx_alarm_severity_ts ON alarm_event(severity,event_ts);
CREATE INDEX idx_ack_alarm_ts ON acknowledgement(alarm_event_id,ack_ts);
COMMIT;
